def min_nops(program):
    n = len(program)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if program[i].isupper():
            j = i - 1
            count = 0
            while j >= 0 and program[j].islower():
                count += 1
                j -= 1

            for k in range(i, n, 4):
                dp[k] = min(dp[k], dp[i] + (k - i))

    return dp[n]

